<?php
namespace App\Http\Controllers;
use App\Models\{Athlete,TrainingSession,TrainingType,User};
use App\Services\SessionWorkflow;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash};
use Illuminate\Validation\ValidationException;

class ApiController extends Controller {
 private function sessionQuery(Request $r,$athleteId=null){$q=TrainingSession::with(['athlete.user','trainingType','creator','reviewer'])->when($athleteId,fn($q)=>$q->where('athlete_id',$athleteId));foreach(['status','training_type_id','athlete_id'] as $f)if($r->filled($f))$q->where($f,$r->input($f));if($r->filled('date'))$q->whereDate('session_date',$r->date);if($r->filled('search'))$q->where(fn($x)=>$x->where('title','like','%'.$r->search.'%')->orWhere('description','like','%'.$r->search.'%')->orWhereHas('athlete',fn($a)=>$a->where('first_name','like','%'.$r->search.'%')->orWhere('last_name','like','%'.$r->search.'%')));return $q->orderBy('session_date')->orderBy('start_time');}
 private function page($q,Request $r){return $q->paginate(min(max((int)$r->input('per_page',15),1),100));}
 public function register(Request $r){$v=$r->validate(['name'=>'required|string|max:255','email'=>'required|email|unique:users,email','password'=>'required|string|min:8|confirmed','athlete_id_number'=>'required|string|max:50|unique:athletes,athlete_id_number','birthdate'=>'required|date|before:today','sex'=>'required|in:male,female','sport'=>'required|string|max:100','team'=>'nullable|string|max:255','address'=>'required|string','contact_number'=>'required|string|max:20','height_cm'=>'nullable|numeric|min:50|max:250','weight_kg'=>'nullable|numeric|min:20|max:300','emergency_contact_name'=>'nullable|string|max:255','emergency_contact_number'=>'nullable|string|max:20']);$user=DB::transaction(function()use($v){$u=User::create(['name'=>$v['name'],'email'=>$v['email'],'password'=>$v['password'],'role'=>'athlete']);$names=explode(' ',$v['name'],2);Athlete::create([...collect($v)->except(['name','email','password','password_confirmation'])->all(),'user_id'=>$u->id,'first_name'=>$names[0],'last_name'=>$names[1]??'']);return $u;});return response()->json(['user'=>$user,'token'=>$user->createToken('stride-web')->plainTextToken],201);}
 public function login(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required|string']);$user=User::where('email',$v['email'])->first();if(!$user||!Hash::check($v['password'],$user->password))throw ValidationException::withMessages(['email'=>'The provided credentials are incorrect.']);return response()->json(['user'=>$user->load('athlete'),'token'=>$user->createToken('stride-web')->plainTextToken]);}
 public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return response()->noContent();} public function user(Request $r){return $r->user()->load('athlete');}
 public function types(Request $r){return TrainingType::when($r->user()->role==='athlete',fn($q)=>$q->where('is_active',true))->orderBy('name')->get();} public function statuses(){return ['scheduled','in_progress','completed','missed','cancelled'];}
 public function profile(Request $r){return $r->user()->athlete()->firstOrFail()->load('user');} public function updateProfile(Request $r){$v=$r->validate(['contact_number'=>'sometimes|required|string|max:20','address'=>'sometimes|required|string','height_cm'=>'nullable|numeric|min:50|max:250','weight_kg'=>'nullable|numeric|min:20|max:300','emergency_contact_name'=>'nullable|string|max:255','emergency_contact_number'=>'nullable|string|max:20','password'=>'nullable|string|min:8|confirmed']);$a=$r->user()->athlete()->firstOrFail();$a->fill(collect($v)->except('password')->all())->save();if(!empty($v['password']))$r->user()->update(['password'=>$v['password']]);return $a->load('user');}
 public function progress(Request $r){$a=$r->user()->athlete()->firstOrFail();$q=$a->trainingSessions();$totals=(clone $q)->selectRaw('status,count(*) as count')->groupBy('status')->pluck('count','status');$done=(clone $q)->where('status','completed');return ['totals'=>$totals,'total_minutes'=>(clone $done)->sum('duration_minutes'),'total_km'=>(clone $done)->sum('distance_km'),'average_exertion'=>round((float)(clone $done)->avg('perceived_exertion'),1),'upcoming_sessions'=>$this->sessionQuery($r,$a->id)->where('status','scheduled')->whereDate('session_date','>=',today())->limit(5)->get(),'completed_sessions'=>$this->sessionQuery($r,$a->id)->where('status','completed')->latest('session_date')->limit(50)->get()];}
 public function mySessions(Request $r){return $this->page($this->sessionQuery($r,$r->user()->athlete()->value('id')),$r);} public function showMy(Request $r,$id){return $this->sessionQuery($r,$r->user()->athlete()->value('id'))->findOrFail($id);} 
 private function sessionRules(){return ['training_type_id'=>'required|exists:training_types,id','title'=>'required|string|max:150','description'=>'nullable|string','session_date'=>'required|date','start_time'=>'required|date_format:H:i','end_time'=>'nullable|date_format:H:i','location'=>'nullable|string|max:150','intensity'=>'sometimes|in:low,medium,high'];}
 public function storeMy(Request $r,SessionWorkflow $w){$v=$r->validate($this->sessionRules());$v['athlete_id']=$r->user()->athlete()->value('id');$w->ensureNoConflict($v);return response()->json(TrainingSession::create([...$v,'created_by'=>$r->user()->id])->load(['athlete','trainingType']),201);}
 public function updateMy(Request $r,$id,SessionWorkflow $w){$s=$this->sessionQuery($r,$r->user()->athlete()->value('id'))->findOrFail($id);abort_unless($s->status==='scheduled',422,'Only scheduled sessions can be edited.');$v=$r->validate($this->sessionRules());$v['athlete_id']=$s->athlete_id;$w->ensureNoConflict($v,$s->id);$s->update($v);return $s->load(['athlete','trainingType']);}
 public function transitionMy(Request $r,$id,string $to,SessionWorkflow $w){$s=$this->sessionQuery($r,$r->user()->athlete()->value('id'))->findOrFail($id);$log=$to==='completed'?$r->validate(['duration_minutes'=>'required|integer|min:1|max:1440','perceived_exertion'=>'required|integer|min:1|max:10','distance_km'=>'nullable|numeric|min:0|max:9999.99','athlete_notes'=>'nullable|string']):null;return $w->transition($s,$to,$log);}
 public function dashboard(){ $total=TrainingSession::count();$statuses=TrainingSession::selectRaw('status,count(*) as count')->groupBy('status')->pluck('count','status');return ['total_athletes'=>Athlete::count(),'total_sessions'=>$total,'sessions_per_status'=>$statuses,'completion_rate'=>$total?round(($statuses['completed']??0)*100/$total,1):0,'todays_sessions'=>TrainingSession::with(['athlete','trainingType'])->whereDate('session_date',today())->orderBy('start_time')->get()]; }
 public function athletes(Request $r){$q=Athlete::with('user')->when($r->filled('sport'),fn($q)=>$q->where('sport',$r->sport))->when($r->filled('search'),fn($q)=>$q->where(fn($x)=>$x->where('first_name','like','%'.$r->search.'%')->orWhere('last_name','like','%'.$r->search.'%')->orWhere('athlete_id_number','like','%'.$r->search.'%')))->orderBy('last_name');return $this->page($q,$r);} public function showAthlete($id){return Athlete::with('user','trainingSessions.trainingType')->findOrFail($id);} private function athleteRules($create=true){return ['athlete_id_number'=>[$create?'required':'sometimes','string','max:50','unique:athletes,athlete_id_number'.($create?'':',')],'first_name'=>[$create?'required':'sometimes','string','max:255'],'last_name'=>[$create?'required':'sometimes','string','max:255'],'birthdate'=>[$create?'required':'sometimes','date','before:today'],'sex'=>[$create?'required':'sometimes','in:male,female'],'sport'=>[$create?'required':'sometimes','string','max:100'],'team'=>'nullable|string|max:255','height_cm'=>'nullable|numeric|min:50|max:250','weight_kg'=>'nullable|numeric|min:20|max:300','address'=>[$create?'required':'sometimes','string'],'contact_number'=>[$create?'required':'sometimes','string','max:20'],'emergency_contact_name'=>'nullable|string|max:255','emergency_contact_number'=>'nullable|string|max:20'];}
 public function storeAthlete(Request $r){$v=$r->validate($this->athleteRules());return response()->json(Athlete::create($v),201);} public function updateAthlete(Request $r,$id){$a=Athlete::findOrFail($id);$v=$this->athleteRules(false);$v['athlete_id_number'][3]='unique:athletes,athlete_id_number,'.$id;$a->update($r->validate($v));return $a->load('user');} public function deleteAthlete($id){Athlete::findOrFail($id)->delete();return response()->noContent();}
 public function sessions(Request $r){return $this->page($this->sessionQuery($r),$r);} public function showSession(Request $r,$id){return $this->sessionQuery($r)->findOrFail($id);} public function storeSession(Request $r,SessionWorkflow $w){$v=$r->validate($this->sessionRules()+['athlete_id'=>'required|exists:athletes,id']);$w->ensureNoConflict($v);return response()->json(TrainingSession::create([...$v,'created_by'=>$r->user()->id])->load(['athlete','trainingType']),201);} public function updateSession(Request $r,$id,SessionWorkflow $w){$s=TrainingSession::findOrFail($id);abort_unless($s->status==='scheduled',422,'Only scheduled sessions can be edited.');$v=$r->validate($this->sessionRules()+['athlete_id'=>'required|exists:athletes,id']);$w->ensureNoConflict($v,$s->id);$s->update($v);return $s->load(['athlete','trainingType']);} public function deleteSession($id){TrainingSession::findOrFail($id)->delete();return response()->noContent();}
 public function adminStatus(Request $r,$id,SessionWorkflow $w){$v=$r->validate(['status'=>'required|in:in_progress,completed,missed,cancelled']);$log=$v['status']==='completed'?$r->validate(['duration_minutes'=>'required|integer|min:1|max:1440','perceived_exertion'=>'required|integer|min:1|max:10','distance_km'=>'nullable|numeric|min:0|max:9999.99','athlete_notes'=>'nullable|string']):null;return $w->transition(TrainingSession::findOrFail($id),$v['status'],$log);} public function review(Request $r,$id){$v=$r->validate(['coach_feedback'=>'required|string']);$s=TrainingSession::findOrFail($id);abort_unless($s->status==='completed',422,'Only completed sessions can be reviewed.');$s->update([...$v,'reviewed_by'=>$r->user()->id,'reviewed_at'=>now()]);return $s->load(['athlete','trainingType','reviewer']);}
 public function storeType(Request $r){return response()->json(TrainingType::create($r->validate(['name'=>'required|string|max:100|unique:training_types,name','description'=>'nullable|string','is_active'=>'boolean'])),201);}public function updateType(Request $r,$id){$t=TrainingType::findOrFail($id);$t->update($r->validate(['name'=>'sometimes|required|string|max:100|unique:training_types,name,'.$id,'description'=>'nullable|string','is_active'=>'boolean']));return $t;}public function deleteType($id){$t=TrainingType::findOrFail($id);if($t->trainingSessions()->exists())throw ValidationException::withMessages(['training_type'=>'Training type is in use by sessions.']);$t->delete();return response()->noContent();}
}
